            "in_savings_withdrawals_take_3_days_to": "{{text}} {{savingsBalance}} {{currency}} у заощадженнях. Виведення займає 3 дні.",
            "swapping_pxa_to_pxs_is_instant_the": "Конвертація PXA у PXS миттєва: половина PXA конвертується одразу, за вирахуванням комісії 5%, а друга половина лишається заблокованою як застава й повертається через ~3,5 дня з урахуванням ціни на момент повернення. Конвертація PXS у PXA відбувається без комісії й завершується через ~3,5 дня за медіанною ціною witnesses на той момент.",
            "pxp_usable_because": "{{text}} <0>{{overall}}</0> PXP доступно, бо <1>{{borrowed}}</1> позичено у інших і <2>{{lended}}</2> позичено іншим.",
            "strong_strong_can_transfer_pixa_power_directly": "<strong>@{{username}}</strong> може переказувати Pixa Power безпосередньо на інший акаунт, оминаючи стандартний 13-тижневий цикл power-down. Ця скарбниця — акаунт із мультипідписом, тож жоден окремий логін не може перемістити її кошти — скористайтеся <strong>Масовим переказом</strong> нижче, де кожен власник ключа окремо підписує один і той самий пакет, перш ніж він буде об’єднаний і трансльований.",
            "the_big_mac_index_is_a_renown": "Індекс Біг-Мака — відомий економічний індекс, що відстежує купівельну спроможність, інфляцію та індекс споживчих цін.",
            "beware_of_spam_and_phishing_links_in": "Остерігайтеся спаму та фішингових посилань у мемо переказів. Не відкривайте посилання від користувачів, яким не довіряєте. Не передавайте свої приватні ключі жодним стороннім сайтам. Транзакції не відображатимуться, доки не будуть підтверджені в блокчейні, що може зайняти кілька хвилин.",
            "are_you_sure_you_want_to_power": "Ви впевнені, що хочете виконати power up {{amount}} PXA? Це перетворить ліквідні PXA на застейкану Pixa Power.",
            "are_you_sure_you_want_to_power_2": "Ви впевнені, що хочете виконати power down {{amount}} PXP? Виплата відбудеться 13 щотижневими частинами.",
            "are_you_sure_you_want_to_swap": "Ви впевнені, що хочете конвертувати {{amount}} PXA у PXS? Половина конвертується одразу, за вирахуванням комісії 5%, і PXS зараховується миттєво. Друга половина лишається заблокованою як застава й повертається через ~3,5 дня з урахуванням ціни PXA на той момент; якщо ціна впаде вдвічі, нічого не повернеться. Конвертацію не можна скасувати.",
