            "full_transfer_ledger_for_the_period_received": "Повний реєстр переказів за період. Отримані перекази — це надходження (вони встановлюють базу вартості); лише відправлення третім сторонам і свопи є оподатковуваними вибуттями, наведеними нижче в «Вибуттях».",
            "opening_received_disposed_closing_per_token_open": "Початок + надійшло − вибуло = кінець, за кожним токеном. Початок відображає баланси, задані в «Розширених».",
            "total_gain_taxable": "Загальний прибуток {{fmtFiat}} {{fiat}} · оподатковується {{fmtFiat_2}} {{fiat_2}} {{fmtFiat_3}} {{fmtFiat_4}} {{fmtFiat_5}}",
            "not_taxable_disposals_or_income_proposal_fees": "Не є оподатковуваними вибуттями чи доходом. Внески за пропозиції залишають акаунт і зменшують ваші активи; завершені виведення із заощаджень і power-up — внутрішні переміщення, показані для повноти.",
            "seen_in_history_but_not_booked_into": "Присутні в історії, але не враховані в цифрах вище ({{skippedTotal}} операцій) — соціальні/управлінські дії без впливу на баланс, дохід, уже врахований при отриманні, або переміщення, розраховані пізнішим виконанням:",
            "reconstructed_from_classified_events": "Реконструйовано з {{ingest}} класифікованих подій.{{text}}{{fiat}}{{text_2}}{{note}}",
            "deductions_optional_losses_you_carried_forward_f": "Відрахування — необов’язково. Збитки, перенесені з попередніх років, компенсують прибутки цього року; сума річного звільнення — це та частина ліміту вашої країни, яку ви вже використали деінде. Застосовуються автоматично там, де ваша юрисдикція їх передбачає.",
            "send_labels_are_assigned_in_the_classify": "Мітки відправлень призначаються на кроці «Класифікація» і запам’ятовуються для кожного акаунта. За бажанням редагуйте їх масово в таблиці:",
            "say_what_each_outbound_send_was_so": "Вкажіть, чим було кожне вихідне відправлення, щоб податок нарахувався правильно. Кожне відправлення вважається оподатковуваним продажем, доки ви не позначите його — мітки власної біржі, власних гаманців, подарунків чи пожертв змінюють податок. Мітки запам’ятовуються. «Продовжити» застосовує їх і перераховує звіт.",
            "nothing_to_classify_no_outbound_transfers_to": "Нічого класифікувати — вихідних переказів третім сторонам у вашій історії не знайдено. Продовжте до перегляду та експорту.",
            "opening_balances_are_tokens_you_already_held": "Початкові баланси — це токени, які ви вже мали до першої зафіксованої операції цього акаунта. Задайте їх, щоб старіші вибуття мали реальну базу вартості замість нульової (завищений прибуток). Вартість — це загальна сума, сплачена за цей початковий обсяг, у {{cur}}.",
            "generate_a_record_of_your_on_chain": "Згенеруйте запис вашої активності в блокчейні за діапазон дат, класифікований для податків рушієм FairFlow. Заповніть опції, класифікуйте відправлення, потім експортуйте як PDF, CSV або JSON.",
            "values_use_the_wallets_current_price_a": "Значення використовують поточну ціну {{fiat}} гаманця — один живий знімок без історичного фіду, тож підсумок активів точний, а реалізовані прибутки приблизні (виручка й база вартості вибуття мають одну поточну ціну). Підключіть історичний оракул / джерело Kursliste для точних прибутків.",
            "fiat_values_come_from_the_engines_pxs": "Фіатні значення походять із демонстраційного постачальника цін рушія з орієнтиром на PXS ({{priceDataVersion}}) — підключіть справжній оракул / джерело Kursliste, перш ніж покладатися на цифри.",
            "prefilled_from_the_chain_1_vest_pxa": "Заповнено з блокчейну: 1 VEST = {{_vestingRateAuto}} PXA, тож 1 000 000 VESTS = {{_vestingRateAuto_2}} PXP. VESTS × це = PXP, а 1 PXP = 1 PXA за вартістю. Редагуйте лише для заміни.",
