            "it_is_earned_through_protocol_emission_not": "Він заробляється через емісію протоколу, а не випускається чи продається компанією. Володіння ним — не акція, не депозит і не обіцянка прибутку; воно не дає права на доходи чи активи будь-якої юридичної особи. Він не рекламується як платіжний токен. Оскільки PXA — це просто PXP у рідкій фазі, той самий висновок FINMA про utility-токен, що стосується PXP (Nutzungs-Token, 27 березня 2025, реф. G01518211), стосується і його — див. повний запис у довідці PXP.",
            "pixa_liquid_pxa": "Pixa Liquid · PXA",
