            "pxa_is_the_working_liquid_of_the": "PXA — робоча рідина мережі. П’ять завдань, одне середовище.",
            "where_the_liquid_comes_from": "Звідки береться рідина",
            "liquid_to_move_solid_to_govern_one": "Рідке, щоб рухатися, тверде, щоб керувати — одне тіло всюди.",
            "liquid_by_design_durable_by_consensus": "Рідке за задумом, тривке за консенсусом.",
            "pxa_is_the_body_0_flowing_0": "PXA — це тіло <0>в русі</0> — <1>рідина</1>, в якій рухається вся економіка.",
            "pixa_is_one_living_being_and_pxa": "Pixa — одна жива істота, а PXA і PXP — її <0>тіло</0> — <1>Атлас</1>, одна субстанція у двох фазах. PXA — <2>рідка фаза</2>: середовище з мінімальними комісіями, в якому ви надсилаєте, торгуєте й розраховуєтесь, і форма, в якій приземляється свідомість (PXS). Виконайте power up — і воно <3>заморожується</3> 1:1 у PXP; виконайте power down — і воно <4>тане</4> назад упродовж тринадцяти тижнів. Воно заробляється роботою, яку виконує мережа, — його не друкує жодна компанія.",
            "power_up_and_pxa_0_freezes_0": "Виконайте power up — і PXA <0>заморожується</0> в PXP, один до одного, миттєво. Виконайте power down — і PXP <1>тане</1> назад у PXA впродовж тринадцятитижневого вивільнення. Одна субстанція, дві фази — разом вони є <2>Атласом</2>, тілом, що несе вагу supra.",
            "no_company_prints_pxa_the_protocol_0": "Жодна компанія не друкує PXA. Протокол <0>карбує його за фіксованим, повільно спадним графіком</0> і спрямовує людям, чия робота дає тілу силу: автори й куратори беруть <1>найбільшу частку</1> кожного блоку, решта платить witnesses, які підтримують ланцюг, та Децентралізованому фонду Pixa. Саме володіння нічого не приносить — <2>винагороди приходять лише за роботу</2>.",
            "the_fixed_shares_of_new_emission_within": "Фіксовані частки нової емісії. У контенті автори беруть 60%, куратори 40% — хто заробляє, вирішують голоси.",
            "pxa_is_the_liquid_equivalent_of_pxp": "PXA — рідкий еквівалент PXP: він не має окремої класифікації й жодних вимог до Pixagram SA."
