            "pxp_is_the_body_0_at_rest": "PXP — це тіло <0>у спокої</0> — <1>вага</1> і <2>голос</2>.",
            "pixa_is_one_living_being_and_pxa": "Pixa — одна жива істота, а PXA і PXP — її <0>тіло</0> — <1>Атлас</1>, одна субстанція у двох фазах. PXP — <2>тверда фаза</2>: PXA, заморожений 1:1, щоб дати істоті <3>вагу</3> (управління) і пропускну здатність без комісій. Це також баласт, що наводить <4>розум</4> — witnesses обираються застейканим PXP, тож розум є тим, що тіло створює про себе саме. Розтопіть його назад у рідкий PXA коли завгодно, через тринадцятитижневе вивільнення, яке жодна сторона не може змінити.",
