            "unstaking_is_gradual_and_fixed_power_down": "Анстейкінг поступовий і фіксований. Виконайте power down — і ваш PXP тане назад у рідкий PXA <0>тринадцятьма рівними щотижневими траншами</0> — близько дев’яноста одного дня. Темп задає протокол; жодна сторона не може його пришвидшити чи сповільнити.",
            "each_week_another_equal_slice_melts_back": "Щотижня ще одна рівна частка тане назад у рідкий PXA, тож ваш баланс стає доступним для витрат у стабільному, передбачуваному підйомі до 100%. Ілюстрація графіка, не наживо.",
            "pxp_is_a_nutzungs_token_a_utility": "PXP — це Nutzungs-Token, утиліті-токен, за висновком FINMA від 27 березня 2025 (реф. G01518211).",
            "it_confers_protocol_functionality_governance_and": "Він надає функціональність протоколу — управління та пропускну здатність без комісій — а не вимогу до доходів чи активів Pixagram SA. Участь в управлінні — не інвестиція; стейкінг для допомоги в роботі протоколу — не схема колективного інвестування. Головне: володіння PXP не приносить <0>жодних відсотків</0> — прибуток походить лише з активної участі — публікацій, голосування, курування — ніколи з пасивної дохідності. Це не платіжний засіб і не депозит — немає емітента, зобов’язаного повернути кошти, і CISA не застосовується."
