            "a_median_across_the_twenty_one_witnesses_rejects": "Медіана серед двадцяти одного witness відкидає корумпованого звітувача; медіана по 84-годинному вікну — три з половиною дні з погодинною вибіркою — відкидає миттєвий сплеск. Дорого корумпувати, повільно маніпулювати: стійкість за побудовою, а не за довірою. Ні центробанку, ні кошика МВФ, ні фіду BIS.",
