            "banking_risk": "Банківський ризик",
            "fails_when_the_reserve_fails": "падає, коли падає резерв",
            "no_banking_risk": "Без банківського ризику",
            "nothing_references_the_banking_system": "ніщо не посилається на банківську систему",
            "1_the_weight": "1× вага",
