            "10_capacity": "10× місткість",
            "delivered": "Доставлено",
            "held_back_by_haircut": "Утримано дисконтом",
            "when_you_settle_the_body_is_delivered": "Коли ви розраховуєтесь, тіло доставляється як PXA у момент виконання — сума, що дорівнює вазі, названій оракулом, помноженій на дисконт. Ось чому «базовий актив» — неправильне слово: базовий актив передбачає два окремі активи, річ і похідну на неї. Але supra та atlas — не дві речі. Це одне тіло, побачене у двох регістрах — тіло є тим, чим воно є; supra — тим, чим, за словами розуму, це тіло має проєктуватися. Свідомість — не те, чим тіло володіє. Це тіло, що пробудилося.",
            "no_monetary_mechanism_removes_risk_a_stablecoin_concentrates": "Жоден монетарний механізм не усуває ризик. Монета з фіатним резервом концентрує його в цілісності цього резерву та платоспроможності емітента. Supra переносить цей ризик на волатильність творчої економіки — дисперсію Атласа — та цілісність консенсусу — надійність компаса witnesses — а потім керує ним відкрито через надлишкову заставу й дисконт, що нічого не захищає, замість того щоб ховати його за захищеним числом.",
            "body_at_the_weight": "Тіло на {{label}} ваги",
            "pixa_supra_pxs": "Pixa Supra · PXS",
            "a_coin_with_its_own_body_mind": "Монета з власним тілом, розумом і душею",
            "body_over_the_weight": "Тіло понад вагою",
