            "minted_only_by_converting_pxa": "Карбується лише протоколом",
            "anatomy_of_a_living_coin": "Анатомія живої монети",
            "the_mind_oracle": "Розум · Oracle",
            "a_compass_not_a_peg": "Компас, а не якір.",
