            "you_are_about_to_request_a_change": "Ви збираєтеся запитати зміну акаунта відновлення для <0>@{{username}}</0>.",
            "nominate_a_trusted_account_a_co_founder": "Призначте довірений акаунт — співзасновника, дочірній гаманець під вашим контролем або контакт, до якого можете достукатися іншим каналом — щоб допомогти вам повернути доступ, якщо ваш ключ owner буде втрачено чи скомпрометовано. Процедура відновлення використовує історію вашого ключа owner, тож акаунт відновлення сам по собі ніколи не зможе захопити ваш акаунт: він може лише допомогти вам його відновити. Зміни набувають чинності після 30-денного вікна очікування.",
            "strong_30_day_waiting_period_strong_changing": "<strong>30-денний період очікування.</strong> Зміна акаунта відновлення не миттєва. Новий запит набуває чинності <strong>через 30 днів після трансляції</strong>; до того чинним залишається поточний акаунт відновлення. Повторна трансляція під час вікна очікування замінює очікуваний запит. Повернення до поточного значення скасовує очікувану зміну.",
            "pick_someone_you_trust_personally_a_co": "Оберіть того, кому довіряєте особисто — співзасновника, дочірній акаунт під вашим контролем або гаманець, з власником якого можете зв’язатися іншим каналом.",
            "generate_a_fresh_seed_phrase_to_derive": "Згенеруйте свіжу сід-фразу, щоб вивести нові ключі для вашого акаунта. Сід-фраза — це майстер-ключ до всіх ключів акаунта — бережіть її й нікому не передавайте. Ключ owner буде використано для підписання транзакції оновлення ключів, коли ви підтвердите нижче.",
            "this_will_strong_cancel_any_pending_recovery": "Це <strong>скасує будь-яку очікувану зміну акаунта відновлення</strong>, повторно транслювавши те саме значення, що й ваш поточний акаунт відновлення. 30-денний очікуваний запит буде замінено; поточний акаунт відновлення залишається чинним увесь час.",
            "once_broadcast_the_chain_will_create_a": "Після трансляції блокчейн створить очікуваний запит, що набуде чинності через <strong>30 днів</strong>. Ваш поточний акаунт відновлення (<0>@{{currentRecovery}}</0>) залишається чинним до того часу. У вас запитають <strong>ключ owner</strong>.",
            "posting_description_1": "Цей ключ використовується для дій у соцмережі: публікацій, коментарів і голосування. Він має обмежений набір прав, і його не можна використовувати для грошових операцій.",
            "posting_description_2": "Використовуйте цей ключ для входу в соцмережі на базі Pixa, як-от Pixagram.com. Зберігайте його в надійному місці.",
            "active_description_1": "Цей ключ має додаткові права для чутливіших грошових операцій, як-от переказ і обмін токенів.",
            "active_description_2": "Під час операцій із гаманцем може знадобитися автентифікація ключем Active. Вводьте Active Key лише в застосунках, яким довіряєте: будь-хто, хто має цей ключ, може забрати ваші токени.",
            "owner_description_1": "Ключ Owner потрібен для зміни інших ключів. Він має додаткові права на відновлення акаунта та зміну інших ключів. Це найважливіший ключ — зберігайте його в надійному місці офлайн.",
            "memo_description_1": "Ключ Memo дещо особливий. Єдине, що він уміє, — шифрувати й розшифровувати особисті повідомлення, які надсилаються через блокчейн.",
            "perm_publish_a_post_or_comment": "Публікація допису або коментаря",
