            "where_can_i_read_the_full_technical": "Де можна прочитати повну технічну специфікацію?",
            "a_public_ledger_and_a_social_platform": "Публічний реєстр і соціальна платформа для піксель-арту.",
            "the_liquid_transferable_token_of_the_pixa": "Ліквідний, переказний токен економіки Pixa.",
