            "above_10_000_the_protocol_pauses_new": "Коли випущені PXS перевищують 20% ринкової капіталізації PXA, протокол припиняє карбування нових PXS.",
            "they_cannot_no_minting_key_exists": "Вони не можуть. Ключа карбування не існує.",
