            "pixasupra_is_a_type_of_token_which": "PixaSupra — supracoin з оракульним орієнтиром, націлений на <0>світове зчитування купівельної спроможності реальних товарів</0>. Протокол не захищає жодного числа, а розрахунок доставляє те, що застава може понести.",
