            "similar_to_most_stablecoin_its_algorithms_requir": "Корекція курсу — це не рука оператора на важелі: witnesses голосують за ціновий фід і параметри протоколу консенсусом, а справедливий APR дає системі змогу слідувати цьому фіду, винагороджуючи довгостроковий стейкінг.",
            "the_blockchain_can_emit_various_ratio_of": "Блокчейн може емітувати різні співвідношення PixaSupra до Pixa. Оскільки PixaSupra конвертується в Pixa за курсом з оракульним орієнтиром, випущений PixaSupra зіставляється з капіталізацією Pixa.",
